const labels={applications:'Applications',review:'Review contributions',mine:'My contributions',products:'Products',orders:'Orders'};
const deliveryLabels={app:'Browser app',email:'Email',whatsapp:'WhatsApp',sms:'SMS'},deliveryStates={accepted:'Accepted',partial:'Partly delivered',fallback:'Used fallback',failed:'Failed',unavailable:'Unavailable'};
