    if(lock.current||blocked.current)return null;
    lock.current=true;setState('saving');setMessage('Saving…');
    try{const next=validate(await request(path,body));setState('ready');setMessage('Saved to your website.');return next;}
    catch(error){blocked.current=true;setState('uncertain');setMessage(error.message||'The save could not be confirmed. Your edits are still here.');return null;}
