        {history.loading&&<p role="status">Opening notification history…</p>}{history.error&&<p role="alert" className="wf-notice">{history.error}</p>}
        <NotificationTimeline items={history.items} history safeLink={safeLink} deliveryLabels={deliveryLabels} deliveryStates={deliveryStates}/>
        {history.loaded&&!history.items.length&&!history.loading&&<p className="wf-notice">No notification history yet.</p>}
