  const data=work.data,disabled=work.busy||work.blocked;
  async function create(e){e.preventDefault();const next=await work.mutate('/products',{name:newName,type:newType,imageId:newImage.id},result=>checkRecord(result,'name'));if(next){work.setData({...data,products:[next,...data.products].slice(0,20)});setNewName('');setNewType('simple');setNewImage({id:0,url:''});setNewOpen(false);setProductDirty(false);setTask('details');setSelected(next);}}
