  if(showShipping)return <Shell config={config} title="Delivery, clearly." intro="See where you deliver and which options your customers can choose." work={work} onRefresh={()=>{if(confirm("Discard local delivery changes and reload saved settings?"))work.refresh();}}><ShippingWorkspace work={work} onClasses={()=>{setShowShipping(false);setShowShippingClasses(true);}} onClose={()=>setShowShipping(false)}/></Shell>;
